code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts = {(r,c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    # The large connected colored object is the template; isolated cells mark copies.
    comps = []
    unseen = set(pts)
    while unseen:
        start = unseen.pop()
        comp = {start}
        stack = [start]
        while stack:
            r,c = stack.pop()
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    q = (r+dr,c+dc)
                    if q in unseen:
                        unseen.remove(q); comp.add(q); stack.append(q)
        comps.append(comp)
    figure_cells = max(comps, key=len)
    mr0 = min(r for r,c in figure_cells); mc0 = min(c for r,c in figure_cells)
    mr1 = max(r for r,c in figure_cells); mc1 = max(c for r,c in figure_cells)
    pattern = [(r-mr0,c-mc0,grid[r][c]) for r,c in figure_cells]
    ar, ac = (mr1-mr0)//2, (mc1-mc0)//2
    out = [row[:] for row in grid]
    for comp in comps:
        if comp is figure_cells:
            continue
        for r,c in comp:
            top,left = r-ar,c-ac
            for dr,dc,v in pattern:
                rr,cc = top+dr,left+dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = v
    return out
'''
